.studio-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:22px}.studio-stat,.publication-card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.studio-stat{padding:18px}.studio-stat strong{display:block;font-size:28px}.publication-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}.publication-card{overflow:hidden}.publication-card img{width:100%;aspect-ratio:16/10;object-fit:cover;background:var(--surface-soft)}.publication-card-body{padding:16px}.publication-card h2{font-size:20px;margin:0 0 5px}.publication-meta{font-size:12px;color:var(--muted);margin:0 0 14px}.status-pill{display:inline-block;padding:4px 8px;border:1px solid var(--line);border-radius:999px;font-size:10px;text-transform:uppercase;letter-spacing:.06em}.status-pill.published{border-color:#79a083;color:#356643;background:#f0f7f1}.empty-studio{padding:42px;text-align:center;background:var(--surface);border:1px dashed var(--line);border-radius:var(--radius)}@media(max-width:700px){.studio-summary{grid-template-columns:1fr}}
