<div class="workspace-header"><div><h1><?=psh(t('Publishing Studio', 'Publishing Studio'))?></h1><p><?=psh(t('Prepare, publish and manage artwork presentations across every channel.', 'Preparar, publicar y gestionar presentaciones de obras en todos los canales.'))?></p></div><a class="button-link primary" href="mockups.php"><?=psh(t('Choose a mockup', 'Elegir un mockup'))?></a></div>
<div class="studio-summary"><div class="studio-stat"><span><?=psh(t('All publications', 'Todas las publicaciones'))?></span><strong><?=count($publications)?></strong></div><div class="studio-stat"><span><?=psh(t('Drafts', 'Borradores'))?></span><strong><?=(int)($counts['draft']??0)?></strong></div><div class="studio-stat"><span><?=psh(t('Published', 'Publicadas'))?></span><strong><?=(int)($counts['published']??0)?></strong></div></div>
<?php if(!$publications):?><div class="empty-studio"><h2><?=psh(t('No publications yet', 'Todavía no hay publicaciones'))?></h2><p><?=psh(t('Open a mockup in the Viewer and choose', 'Abrí un mockup en el Viewer y elegí'))?> <strong><?=psh(t('Publish', 'Publicar'))?></strong> <?=psh(t('to begin.', 'para empezar.'))?></p><a class="button-link primary" href="mockups.php"><?=psh(t('Open Mockup Album', 'Abrir álbum de mockups'))?></a></div><?php else:?><div class="publication-grid"><?php foreach($publications as $publication):?><article class="publication-card"><?php if($publication['source_image_file']):?><img src="media.php?file=<?=rawurlencode(basename((string)$publication['source_image_file']))?>" alt=""><?php endif;?><div class="publication-card-body"><span class="status-pill <?=psh($publication['status'])?>"><?=psh($publication['status'])?></span><h2><?=psh($publication['title'] ?: t('Untitled artwork', 'Obra sin título'))?></h2><p class="publication-meta"><?=(int)$publication['item_count']?> <?=psh(t('mockups', 'mockups'))?> · <?=psh($publication['visibility'])?></p><a class="button-link secondary" href="prepare_publication.php?id=<?=(int)$publication['id']?>"><?= psh($publication['status']==='published' ? t('Manage publication', 'Gestionar publicación') : t('Continue editing', 'Seguir editando')) ?></a><?php if($publication['status']==='published'):?> <a class="button-link secondary" target="_blank" href="public_artwork.php?slug=<?=rawurlencode((string)$publication['slug'])?>"><?=psh(t('View landing', 'Ver página pública'))?></a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?>
